Method.Source:
/// <summary>
/// designed by AVANADE WEN
/// </summary>
protected void updateAfterCopy()
{
    next updateAfterCopy();

    DocuRef docuRef;

    while select docuRef order by docuRef.KCS_TCVLineNum
                         where docuRef.RefTableId == this.sourceRecord().tableid
                            && DocuRef.RefRecId == this.sourceRecord().recId
    {
        DocuRef::createFromDocuRef(DocuRef, this.salesQuotationLine.RecId, tableNum(salesQuotationLine));
    }
}
